files.content:
terraform {
  required_version = ">= 1.5.0, < 2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.63.0, < 7.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = local.tags
  }
}

variable "aws_region" {
  type        = string
  description = "AWS Region selected by the immutable Architecture Document."
  default     = "us-east-1"
}

variable "event_step_functions_task_artifact_path" {
  type        = string
  description = "Stable relative package output produced by the separate Prompt 32A workload builder."
  default     = "../application/artifacts/workload_event_step_functions_task/function.zip"
  validation {
    condition     = can(regex("^\\.\\.?/", var.event_step_functions_task_artifact_path))
    error_message = "Package path must be repository-relative and begin with ./ or ../; absolute machine paths are forbidden."
  }
}

variable "stage" {
  type        = string
  description = "Architecture variable stage."
  default     = "test"
}

locals {
  tags = {
    CloudMarkupArchitecture     = "architecture_event_step_functions_task"
    CloudMarkupRevision         = "revision_event_step_functions_task_1"
    CloudMarkupSolutionRevision = "solution_notes_revision_1"
    ManagedBy                   = "CloudMarkup"
  }
}

resource "aws_lambda_function" "event_step_functions_task" {
  function_name                  = "event_step_functions_task"
  description                    = "CloudMarkup notes-API workload."
  role                           = aws_iam_role.notes_role.arn
  handler                        = "index.handler"
  runtime                        = "nodejs24.x"
  architectures                  = ["arm64"]
  memory_size                    = 256
  reserved_concurrent_executions = 10
  timeout                        = 30
  filename                       = var.event_step_functions_task_artifact_path
  source_code_hash               = filebase64sha256(var.event_step_functions_task_artifact_path)
  tracing_config {
    mode = "Active"
  }
  environment {
    variables = {
      "APP_STAGE" = var.stage
    }
  }
  tags = local.tags
}

data "aws_iam_policy_document" "event_logs_policy_step_functions_task" {
  statement {
    sid       = "eventlogspolicystepfunctionstask"
    effect    = "Allow"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = [format("%s:*", aws_cloudwatch_log_group.event_logs_step_functions_task.arn)]
  }
}

data "aws_iam_policy_document" "trust_policy" {
  statement {
    sid     = "trustpolicy"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "workflow_invoke" {
  statement {
    sid       = "workflowinvoke"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = [aws_lambda_function.event_step_functions_task.arn]
  }
}

data "aws_iam_policy_document" "workflow_trust" {
  statement {
    sid     = "workflowtrust"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "workflow_invoke" {
  name   = "workflow_invoke"
  role   = aws_iam_role.image_workflow_role.name
  policy = data.aws_iam_policy_document.workflow_invoke.json
}

resource "aws_iam_role_policy" "event_logs_policy_step_functions_task" {
  name   = "event_logs_policy_step_functions_task"
  role   = aws_iam_role.notes_role.name
  policy = data.aws_iam_policy_document.event_logs_policy_step_functions_task.json
}

resource "aws_cloudwatch_log_group" "image_workflow_logs" {
  name              = "/aws/vendedlogs/states/image-workflow"
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}

resource "aws_sfn_state_machine" "image_workflow" {
  name     = "image-workflow"
  type     = "STANDARD"
  role_arn = aws_iam_role.image_workflow_role.arn
  definition = jsonencode({
    Comment        = "CloudMarkup catalog-derived workflow"
    StartAt        = "Task_lambda_8f216a886e"
    TimeoutSeconds = 300
    States = {
      "Task_lambda_8f216a886e" = {
        Type           = "Task"
        Resource       = aws_lambda_function.event_step_functions_task.arn
        TimeoutSeconds = 60
        End            = true
        Retry = [{
          ErrorEquals     = ["States.ALL"]
          IntervalSeconds = 2
          MaxAttempts     = 2
          BackoffRate     = 2
        }]
      }
    }
  })
  logging_configuration {
    include_execution_data = false
    level                  = "ERROR"
    log_destination        = format("%s:*", aws_cloudwatch_log_group.image_workflow_logs.arn)
  }
  tracing_configuration {
    enabled = true
  }
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}

resource "aws_cloudwatch_log_group" "event_logs_step_functions_task" {
  name              = "/aws/lambda/notes_handler"
  log_group_class   = "STANDARD"
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}
